⚙️ **Arduino Uno + DHT22 + 0.96 inch I2C OLED (SSD1306) Setup:**

1. **Circuit Wiring (पिन कनेक्शन):**
   • **DHT22:** VCC -> 5V, GND -> GND, Data -> Digital Pin D2 (10k Pull-up resistor between VCC & Data).
   • **OLED Display (I2C):** VCC -> 5V, GND -> GND, SCL -> A5, SDA -> A4.

2. **Libraries Required:** `Adafruit SSD1306`, `Adafruit GFX`, `DHT sensor library`.

3. **Arduino Code:**
```cpp
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <DHT.h>

#define DHTPIN 2
#define DHTTYPE DHT22
DHT dht(DHTPIN, DHTTYPE);
Adafruit_SSD1306 display(128, 64, &Wire, -1);

void setup() {
  dht.begin();
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();
  display.setTextColor(WHITE);
}

void loop() {
  float h = dht.readHumidity();
  float t = dht.readTemperature();
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 10);
  display.print("GramSetu Agri-IoT");
  display.setTextSize(2);
  display.setCursor(0, 30);
  display.print("T: "); display.print(t, 1); display.print(" C");
  display.setCursor(0, 50);
  display.print("H: "); display.print(h, 1); display.print(" %");
  display.display();
  delay(2000);
}
```

